const metric=(label,value,detail='')=>`<div class="metric"><div class="label">${label}</div><div class="value">${value}</div><div class="detail">${detail}</div></div>`;
function comparisonTable(results){
 const rows=[...(result.assumptions.goal==='fi'?[['Reached FI at deadline · observed',r=>pct(r.fiSuccessRate)],['Missed FI deadline · observed (includes depletion)',r=>pct(r.fiMissRate)]]:[]),['Calculated starting annual withdrawals',r=>money(r.initial.spending)],['Initial cash / stock allocation',r=>`${pct(r.initial.cash/result.assumptions.portfolio)} cash / ${pct(r.initial.investment/result.assumptions.portfolio)} stocks`],['Modeled initial success · no later adjustments',r=>pct(r.initial.probability)],['Average annual real withdrawals',r=>money(r.averageAnnual)],['Total withdrawals over period · mean',r=>money(r.metrics.total.mean)],['Total withdrawals over period · 10th / median / 90th',r=>[r.metrics.total.p10,r.metrics.total.median,r.metrics.total.p90].map(money).join(' / ')],['Lowest annual withdrawals · 10th / median / 90th',r=>[r.metrics.lowest.p10,r.metrics.lowest.median,r.metrics.lowest.p90].map(money).join(' / ')],['Years at zero withdrawals · mean / 90th',r=>number(r.metrics.floorYears.mean)+' / '+number(r.metrics.floorYears.p90)],['Target unattainable at least once',r=>pct(r.unattainableRate)],['Longest consecutive stretch at zero withdrawals · median / 90th',r=>number(r.metrics.maxFloorRun.median)+' / '+number(r.metrics.maxFloorRun.p90)+' years'],['Checkpoints unreachable even at zero · mean',r=>number(r.metrics.zeroLimited.mean)],['Average number of cuts',r=>number(r.metrics.cuts.mean)],['Average cut · across triggered cuts',r=>`${pct(r.averageCut)} / ${money(r.averageCutDollars)}`],['Largest single cut · worst path',r=>`${pct(r.metrics.maxCut.max)} / ${money(r.metrics.maxCutDollars.max)}`],['Worst drop below initial withdrawals · median / 90th percentile',r=>`${pct(r.metrics.decline.median)} / ${pct(r.metrics.decline.p90)}`],['Longest stretch below initial withdrawals · median / 90th percentile',r=>`${number(r.metrics.maxBelowInitialRun.median)} / ${number(r.metrics.maxBelowInitialRun.p90)} years`],['Withdrawal volatility · mean annual-change standard deviation',r=>pct(r.metrics.volatility.mean)],['Portfolio depletion · observed',r=>pct(r.depletionRate)],['Any withdrawal shortfall · observed',r=>pct(r.shortfallRate)],['Shortfall before final 10 years · observed',r=>pct(r.earlyShortfallRate)],['All withdrawals funded · observed',r=>pct(r.fundedRate)],['Ending-balance goal met with withdrawals funded',r=>pct(r.actualSuccess)],['Ending portfolio · today’s dollars · 10th / median / 90th',r=>`${money(r.balances.at(-1).p10)} / ${money(r.balances.at(-1).median)} / ${money(r.balances.at(-1).p90)}`],['Years below lower rail before adjustment · mean',r=>number(r.metrics.below.mean)],['Longest consecutive lower-rail streak · mean',r=>number(r.metrics.maxRunBelow.mean)],['Years still below lower rail after adjustment · mean',r=>number(r.metrics.afterBelow.mean)],['Target could not be restored · average checkpoints',r=>number(r.metrics.limited.mean)],['At least one cut in first 5 / 10 / 20 years',r=>r.firstCut.map((p,i)=>result.assumptions.years<[5,10,20][i]?'N/A':pct(p)).join(' / ')]];
 return `<div class="table-scroll"><table class="gr-table"><thead><tr><th>Measure</th>${results.map(r=>`<th>${escape(r.strategy.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><td>${label}</td>${results.map(r=>`<td>${fn(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function renderReferences(){
 const a=result.assumptions,success=r=>pct(a.goal==='fi'?r.fiSuccessRate:r.actualSuccess);
 return `<section class="panel content-panel"><h2>What do the withdrawal adjustments change?</h2><p>Guardrails can trade some chance of reaching the goal for more withdrawals. Compare them with keeping withdrawals fixed or taking none.</p><details><summary>How these references are calculated</summary><p>Each fixed baseline starts with the same withdrawals and follows your inflation choice without guardrail adjustments. Each zero-withdrawal reference retains the same initial stocks and cash, and the same original cash reserve dollar target. All use identical markets. Guardrails allow increases as well as cuts; higher withdrawals can reduce the chance of reaching FI. They do not necessarily improve deadline success.</p></details><div class="table-scroll"><table class="gr-table"><thead><tr><th>Strategy / rule</th><th>Observed goal success</th><th>Total real withdrawals · median (10th–90th)</th><th>Lowest annual withdrawals · median</th></tr></thead><tbody>${result.references.map((ref,i)=>[[result.results[i],'Scheduled guardrails'],[ref.fixed,'Fixed withdrawals'],[ref.zero,'Zero withdrawals']].map(([r,label])=>`<tr><td>${escape(ref.name)} · ${label}</td><td>${success(r)}</td><td>${money(r.metrics.total.median)} (${money(r.metrics.total.p10)}–${money(r.metrics.total.p90)})</td><td>${money(r.metrics.lowest.median)}</td></tr>`).join('')).join('')}</tbody></table></div></section>`;
}
function projectionDollars(){return `<div class="section-head"><p>Projection amounts: ${futureDollars?'future dollars, using each sampled path’s inflation':'today’s purchasing power'}. Cut-size details stay in today’s dollars.</p><div class="segmented"><button data-gr-dollars="real" class="${!futureDollars?'active':''}">Today’s dollars</button><button data-gr-dollars="nominal" class="${futureDollars?'active':''}">Future dollars</button></div></div>`;}
function bindDollarControls(){root.querySelectorAll('[data-gr-dollars]').forEach(b=>b.onclick=()=>{futureDollars=b.dataset.grDollars==='nominal';onDollarChange?.(futureDollars);renderResults();});}
function renderResults(){
 if(!root||!result)return;if(result.kind==='schedules'){renderScheduleResults();return;}const [a,b]=result.results;if(result.assumptions.goal!=='fi'&&['fiSuccess','fiMiss'].includes(sweepView))sweepView='annual';
 root.querySelector('#gr-results').innerHTML=`${projectionDollars()}<section class="panel content-panel"><h2>Success and withdrawals, side by side</h2><p>${outcomeSummary(result.results,result.assumptions)}</p><p class="hint">Observed success includes future rule adjustments; starting confidence assumes none. Probability targets are the estimates used to trigger those adjustments. Projection amounts follow the selected dollar view.</p></section>
 <div class="gr-strategies">${result.results.map((r,i)=>`<section class="panel content-panel gr-strategy" style="border-top-color:${colors[i]}"><h2>${escape(r.strategy.name)}</h2><p>${escape(r.strategy.schedule||'fixed')} schedule · ${pct(r.strategy.target)} starting target → ${pct(scheduledStrategy(r.strategy,result.assumptions.years-1,result.assumptions.years).target)} final-checkpoint target</p>${r.initial.limited?`<div class="notice">${r.initial.unreachable?`Even zero withdrawals give only ${pct(r.initial.zeroProbability)} modeled success, below the ${pct(r.strategy.target)} target. Withdrawals alone cannot restore it.`:'Available withdrawals cannot restore the initial probability target.'} Achieved estimate: ${pct(r.initial.probability)}.</div>`:''}<div class="metrics gr-headline">${metric(result.assumptions.goal==='fi'?'FI target met at deadline':'Retirement goal met',pct(result.assumptions.goal==='fi'?r.fiSuccessRate:r.actualSuccess),Math.round((result.assumptions.goal==='fi'?r.fiSuccessRate:r.actualSuccess)*result.assumptions.count).toLocaleString()+' of '+result.assumptions.count.toLocaleString()+' paths')}${metric('Calculated starting annual withdrawals',money(r.initial.spending),money(r.initial.spending/12)+' per month')}${metric('Total withdrawals through deadline',money((futureDollars?r.nominal.total:r.metrics.total).median),futureDollars?'Median · future dollars summed across years':'Median · today’s dollars')}${metric('Chance of at least one cut',pct(r.anyCutRate))}${metric('Chance of zero withdrawals',pct(r.anyZeroRate),r.zeroYearsWhenAffected?number(r.zeroYearsWhenAffected.mean)+' years on average among affected paths':'No paths reached zero')}${metric('Years at zero withdrawals',number(r.metrics.floorYears.mean),'Average across simulated paths')}</div><p>${number(r.metrics.cuts.mean)} withdrawal cuts on average. Median lowest annual withdrawal: ${money(r.metrics.lowest.median)}.</p><p>${pct(r.unattainableRate)} of simulations had a checkpoint where the target could not be reached even with zero withdrawals. <span class="hint">Raising the target does not ensure it is achievable.</span></p></section>`).join('')}</div>
 <div class="panel content-panel"><h2>What this run shows</h2><p>${escape(a.strategy.name)} starts at ${money(a.initial.spending)}, versus ${money(b.initial.spending)} for ${escape(b.strategy.name)}. It has ${number(a.metrics.cuts.mean)} cuts on average versus ${number(b.metrics.cuts.mean)}, with average reductions of ${pct(a.averageCut)} versus ${pct(b.averageCut)}. ${result.assumptions.goal==='fi'?`Observed FI success at the deadline is ${pct(a.fiSuccessRate)} versus ${pct(b.fiSuccessRate)}.`:`Observed depletion is ${pct(a.depletionRate)} versus ${pct(b.depletionRate)}.`}</p><p>${result.assumptions.goal==='fi'?`The total-assets target and original deadline stay fixed. After one year, there are ${result.assumptions.years-1} years remaining. Missing FI and exhausting the portfolio are different outcomes; the detailed table reports both.`:`Before the final 10 years, observed withdrawal shortfalls are ${pct(a.earlyShortfallRate)} versus ${pct(b.earlyShortfallRate)}. As the horizon shortens, the rules may raise withdrawals sharply; a bad year can then exhaust the portfolio before the next checkpoint. These outcomes depend on the chosen assumptions and probability estimator. Higher withdrawals today can come with more variable withdrawals later; averages can also be influenced by a small number of very favorable paths.`}</p><details><summary>All withdrawal, cut and risk measures</summary>${comparisonTable(result.results)}<p class="chart-caption">Worst drop is the largest shortfall below first-year withdrawals. Duration is the longest consecutive stretch below that level, calculated separately. Cut sizes refer to planned guardrail cuts; withdrawal shortfalls are reported separately. Dollar and percentage maxima may occur on different paths.</p></details></div>
 <p class="notice">${result.results.map((r,i)=>{const fixed=result.references[i].fixed;return `${escape(r.strategy.name)}: ${pct(result.assumptions.goal==='fi'?r.fiSuccessRate:r.actualSuccess)} observed success with guardrails, versus ${pct(result.assumptions.goal==='fi'?fixed.fiSuccessRate:fixed.actualSuccess)} with fixed withdrawals.`;}).join(' ')} Withdrawal increases can exchange some chance of reaching the goal for more withdrawals. See the comparison below.</p>${renderReferences()}<section class="panel content-panel"><div class="section-head"><h2>How do withdrawals change over time?</h2></div><div class="scenario-controls">${select('spendingView','Show',{median:'Median withdrawals',p10:'10th percentile',p90:'90th percentile',path:'Individual simulated path'},spendingView,false)}${select('pathIndex','Shared path',Object.fromEntries(a.examples.map((_,i)=>[i,'Path '+(i+1)])),pathIndex,false)}</div><div id="gr-chart-a"></div><div id="gr-decisions"></div><p class="chart-caption">Actual funded withdrawals. Matching path numbers have exactly the same returns and inflation for both strategies. Shading shows the 10th–90th percentiles. The median is a cross-path summary, not one simulated experience.</p></section>
 <section class="panel content-panel"><h2>How often and how much are withdrawals cut?</h2><div class="gr-strategies"><div id="gr-chart-b-count"></div><div id="gr-chart-b-size"></div></div><h3>Distribution of each simulated path’s largest cut</h3><div id="gr-chart-b-dist"></div><p class="chart-caption">Bins include paths without cuts in the first 0–10% bin. The largest-cut percentiles below include paths without cuts.</p><div class="metrics">${result.results.map(r=>metric(escape(r.strategy.name)+' largest cut',pct(r.metrics.maxCut.median),'10th–90th percentile: '+pct(r.metrics.maxCut.p10)+'–'+pct(r.metrics.maxCut.p90))).join('')}</div></section>
 <section class="panel content-panel"><h2>What changes with a higher probability target?</h2>${select('sweepView','Outcome',{initial:'Calculated starting annual withdrawals',annual:'Average annual withdrawals over period',cuts:'Average number of cuts',maxCut:'Median largest withdrawal cut',depletion:'Actual portfolio depletion rate',...(result.assumptions.goal==='fi'?{fiSuccess:'Reached FI at deadline',fiMiss:'Missed FI deadline'}:{})},sweepView,false)}<div id="gr-chart-c"></div><p class="chart-caption">This sweep uses fixed targets, independent of the schedules selected above. Each point uses lower/upper guardrails 10 percentage points around its target, clamped to 0–100%, with the same ${number(result.assumptions.count)} outer paths.</p></section>
 <section class="panel content-panel"><h2>How do portfolio balances change?</h2>${select('balanceView','Balance',{total:'Total portfolio',investment:'Investments only',cash:'Cash only'},balanceView,false)}<div id="gr-chart-d"></div><p class="chart-caption">Lines are medians; shaded ranges show the 10th–90th percentiles. Separate cash and investment medians need not add to the total median.</p></section>
 ${result.noCash?`<section class="panel content-panel"><h2>Cash reserve versus no reserve</h2><p>Same markets and targets. Each cash policy has its own independently built probability model with starting withdrawals recalculated for each cash policy; no-cash scenarios put all starting wealth into investments.</p><p>No-reserve independent probability check: mean error ${pp(result.noCashCalibration.meanError)}, maximum ${pp(result.noCashCalibration.maxError)}.</p>${comparisonTable([...result.results.map(r=>({...r,strategy:{...r.strategy,name:r.strategy.name+' · cash'}})),...result.noCash.map(r=>({...r,strategy:{...r.strategy,name:r.strategy.name+' · no cash'}}))])}</section>`:''}
 <section class="panel content-panel"><h2>Model and accuracy</h2><p>${modelDescription(result)} Cash earns a configurable fixed nominal return (${pct(result.assumptions.cashReturn)}). Cash reserves are part of starting wealth, and each strategy receives the same sampled market paths.</p>
 <div class="notice ${result.calibration.maxError>.05?'':'good'}">Independent probability check: average absolute error ${pp(result.calibration.meanError)}; largest error ${pp(result.calibration.maxError)} across ${result.calibration.checks.length} test states and ${number(result.calibration.count)} separate paths. ${result.calibration.maxError>.05?'Some estimates differ by more than 5 percentage points. Increase probability samples and treat close guardrail decisions cautiously.':'This checks the approximation against the same model, not against future markets.'}</div>
 <details><summary>Reproducibility, timing and limitations</summary><p>Outer seed: ${result.pathSeed}; probability seed: ${result.probabilitySeed}; validation seed: ${result.validationSeed}. ${number(result.assumptions.count)} outer paths per strategy, ${number(result.assumptions.innerCount)} probability paths. ${result.assumptions.goal==='fi'?'The FI lookup also interpolates the fixed total-assets target relative to current total wealth, using 322 target-ratio points from 0 to 10,000. Ratios above that range are conservatively assigned 0%; near-tail estimates remain uncertain. Success requires investments plus cash at or above the target on the deadline after withdrawals and cash replenishment. Earlier target touches do not stop the simulation.':''} The lookup covers each remaining year, 11 cash fractions and 161 withdrawal-rate points (zero cash only when reserves are off and no current cash is entered). Earlier checkpoints use interpolated probabilities. The final checkpoint uses direct sampled outcomes; zero-volatility parametric runs use deterministic outcomes. Discrete outcomes may not exactly match a requested target. Maximum lookup monotonic correction: ${pp(result.calibration.maxMonotonicCorrection)}.</p><p>The probability model follows the selected withdrawal inflation policy with no future guardrail adjustments and the same cash policy. It uses independent future paths, never the future of the actual simulated path. Finite samples cannot establish literal 0% or 100% certainty: maximum approximate 95% sampling margin is ±${pp(result.calibration.innerMargin95)}, excluding interpolation and model error. Near-tail estimates are treated as sample bounds. Average near-tail checkpoints: ${result.results.map(r=>escape(r.strategy.name)+' '+number(r.metrics.tail.mean)).join('; ')}.</p><p>At each year’s start, remaining horizon includes that year. After any adjustment, stock and cash receive that year’s return and inflation adjustment once. Withdrawals happen at year-end: cash first after negative or zero nominal stock returns; investments first after positive returns, with cash covering any shortage. Only positive stock-return years replenish cash, by transferring investments toward the reserve target. There is no fixed 85/15 rebalance. The same rule is used in probability estimates and outer scenarios.</p><p>Withdrawal and balance summaries are in starting-year purchasing power. Cash reserve targets change with planned withdrawals. Withdrawals are nonnegative; target restoration is bounded by available wealth and 100% annual withdrawals/assets. A restoration miss over 1.5 percentage points is counted. Depletion means total assets at or below $0.01; fully funded success means no withdrawal shortfall above $0.01. A final-year full withdrawal can deplete assets without a withdrawal shortfall. Planned withdrawals above current wealth is outside the model’s limit and treated as infeasible (0%); it is not given the probability for a smaller withdrawal. A binding floor may still exceed available wealth. The floor can increase failures, which are measured rather than hidden.</p><p>Annual bootstrap years are independent; within-year stock/inflation pairing is retained, but multi-year regimes and serial correlation are not. Parametric stock returns are independent lognormal draws with configurable arithmetic mean and standard deviation, and fixed inflation. Taxes, fees, pensions, mortality, and behavioral limits are not modeled. Later-life withdrawal increases have no additional cap beyond wealth; this can materially affect lifetime averages and last-year failure rates in retirement-funding mode.</p><p>Data: <a href="${result.source.source}" target="_blank" rel="noopener">${escape(result.source.author)} historical returns workbook</a>, ${result.source.period}, retrieved ${result.source.retrieved}; ${escape(result.source.sheet)}, ${escape(result.source.columns)}. Pre-1957 stock observations are the source’s predecessor series. The bundled source contains numeric facts only; no data is fetched while you run a simulation.</p><div class="table-scroll"><table class="gr-table"><thead><tr><th>Years left</th><th>Cash</th>${result.assumptions.goal==='fi'?'<th>FI target / wealth</th>':''}<th>Estimated</th><th>Independent estimate</th><th>Error</th></tr></thead><tbody>${result.calibration.checks.map(c=>`<tr><td>${c.years}</td><td>${pct(c.cashFraction)}</td>${result.assumptions.goal==='fi'?`<td>${number(c.targetRatio)}×</td>`:''}<td>${pct(c.estimated)}</td><td>${pct(c.observed)}</td><td>${pp(c.error)}</td></tr>`).join('')}</tbody></table></div></details></section>`;
 for(const section of root.querySelectorAll('#gr-results > .panel')){const heading=section.querySelector('h2');if(!heading)continue;const title=heading.textContent;if(title==='What this run shows'||['How often and how much are withdrawals cut?','What changes with a higher probability target?','How do portfolio balances change?'].includes(title)||title==='What do the withdrawal adjustments change?'||title==='Model and accuracy'||title==='Cash reserve versus no reserve'){const details=document.createElement('details'),summary=document.createElement('summary');details.className=section.className;summary.textContent=title;heading.remove();details.append(summary,...section.childNodes);section.replaceWith(details);details.addEventListener('toggle',()=>{if(details.open&&root&&result)drawResults();});}}
 for(const id of ['spendingView','pathIndex','sweepView','balanceView'])root.querySelector('#gr-'+id).oninput=e=>{if(id==='spendingView')spendingView=e.target.value;if(id==='pathIndex')pathIndex=Number(e.target.value);if(id==='sweepView')sweepView=e.target.value;if(id==='balanceView')balanceView=e.target.value;drawResults();};
 drawResults();bindDollarControls();
}
function modelDescription(r){const block=` Historical blocks contain ${r.assumptions.blockYears??1} consecutive year(s); separate blocks are independent. `;return r.assumptions.model==='parametric'?`Parametric model: ${pct(r.assumptions.stockMean)} nominal stock mean, ${pct(r.assumptions.stockVol)} volatility and ${pct(r.assumptions.inflation)} inflation.`:r.assumptions.model==='historical'?block+`Unchanged paired bootstrap of ${r.source.period} data. Historical arithmetic means: ${pct(r.historicalMean)} stocks and ${pct(r.historicalInflation)} inflation. Expected-return inputs are not applied.`:block+`Paired bootstrap of ${r.source.period} data, rescaling gross stock returns and gross inflation so their arithmetic means are ${pct(r.assumptions.stockMean)} and ${pct(r.assumptions.inflation)}. This is adjusted historical sampling, not a literal historical replay.`;}
function drawResults(){
 if(result.kind==='schedules'){drawScheduleResults();return;}
 const [a,b]=result.results;
 const spending=result.results.map((r,i)=>({name:r.strategy.name,color:colors[i],points:(futureDollars?r.nominal.spending:r.spending).map((row,y)=>({x:row.year,y:spendingView==='path'?(futureDollars?r.examples[pathIndex].nominalSpending:r.examples[pathIndex].spending)[y]:row[spendingView],...(spendingView==='median'?{low:row.p10,high:row.p90}:{})}))}));
 plot('#gr-chart-a',spending,{label:futureDollars?'Annual future-dollar withdrawals':'Annual real withdrawals',format:money});root.querySelector('#gr-pathIndex').disabled=spendingView!=='path';
 bars('#gr-chart-b-count',result.results.map((r,i)=>({name:r.strategy.name,value:r.metrics.cuts.mean,color:colors[i]})),'Average number of cuts',number);
 bars('#gr-chart-b-size',result.results.map((r,i)=>({name:r.strategy.name,value:r.averageCut,color:colors[i]})),'Average reduction per cut',pct);
 plot('#gr-chart-b-dist',result.results.map((r,i)=>({name:r.strategy.name,color:colors[i],points:r.histogram.map(h=>({x:(h.lower+h.upper)/2,y:h.count/result.assumptions.count}))})),{label:'Share of simulated paths by largest-cut bin',format:pct,xFormat:pct,xLabel:'Largest cut (10-point bins)'});
 plot('#gr-chart-c',[{name:root.querySelector('#gr-sweepView').selectedOptions[0].textContent,color:colors[0],points:result.sweep.map(r=>({x:r.target,y:r[sweepView]}))}],{label:'Target probability tradeoffs',format:['depletion','maxCut','fiSuccess','fiMiss'].includes(sweepView)?pct:sweepView==='cuts'?number:money,xFormat:pct,xLabel:'Target probability'});
 const balanceSeries=result.results.map((r,i)=>({name:r.strategy.name,color:colors[i],points:(futureDollars?r.nominal.balances:r.balances).map(row=>{const v=balanceView==='total'?row:row[balanceView];return {x:row.year,y:v.median,low:v.p10,high:v.p90};})}));
 if(guardrailGoalTarget(result.assumptions)>0&&balanceView==='total')balanceSeries.push({name:futureDollars?'Ending target · median inflation':'Ending total-assets target',color:'var(--muted)',points:(futureDollars?result.results[0].nominal.balances:result.results[0].balances).map(row=>({x:row.year,y:futureDollars?row.target.median:guardrailGoalTarget(result.assumptions)}))});
 plot('#gr-chart-d',balanceSeries,{label:futureDollars?'Future-dollar portfolio balances':'Real portfolio balances',format:money});
 root.querySelector('#gr-decisions').innerHTML=spendingView==='path'?`<details><summary>Annual decisions for shared path ${pathIndex+1}</summary><p class="chart-caption">Probabilities are measured before each adjustment, using the remaining years. Withdrawals are then paid at year-end. ${result.assumptions.goal==='fi'?'The original FI deadline does not move.':''}</p><div class="table-scroll"><table><thead><tr><th>Year</th><th>Years left</th>${result.results.map(r=>`<th>${escape(r.strategy.name)} probability</th><th>Target / rails</th><th>Planned withdrawals</th><th>Decision</th>`).join('')}</tr></thead><tbody>${a.spending.map((row,y)=>`<tr><td>${y+1}</td><td>${result.assumptions.years-y}</td>${result.results.map(r=>{const p=r.examples[pathIndex],w=p.plannedSpending[y],previous=p.plannedSpending[y-1];return `<td>${pct(p.probabilities[y])}</td><td>${pct(p.targets[y].target)} (${pct(p.targets[y].lower)}–${pct(p.targets[y].upper)})</td><td>${money(futureDollars?w*p.priceLevels[y]:w)}</td><td>${p.feasibilities[y].zeroLimited?'Unreachable at zero · ':p.feasibilities[y].floorLimited?'Floor blocks target · ':''}${p.decisions[y]==='cut'?'Cut':p.decisions[y]==='raise'?'Raise':'Maintain'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></details>`:'';
}
function plot(selector,series,{label,format=money,xFormat=number,xLabel='Year',yMax=null}={}){
 if(['Year','Years elapsed'].includes(xLabel)&&assumptions.sourceTimeEntry==='age'&&Number.isFinite(assumptions.sourceAge)){xFormat=v=>number(assumptions.sourceAge+v);xLabel='Age';}
 const host=root.querySelector(selector),W=Math.max(300,Math.min(820,host.clientWidth||820)),H=310,L=85,R=20,T=20,B=48,points=series.flatMap(s=>s.points),minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(minX+1e-9,...points.map(p=>p.x)),maxY=yMax??Math.max(1e-9,...points.map(p=>p.high??p.y))*1.08;
 const x=v=>L+(v-minX)/(maxX-minX)*(W-L-R),y=v=>H-B-v/maxY*(H-T-B);
 let svg='';for(let i=0;i<=4;i++){const v=maxY*i/4;svg+=`<line class="grid" x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end">${format(v)}</text>`;}
 const ticks=W<500?3:5;for(let i=0;i<=ticks;i++){const v=minX+(maxX-minX)*i/ticks;svg+=`<text x="${x(v)}" y="${H-25}" text-anchor="middle">${xFormat(v)}</text>`;}svg+=`<text x="${W/2}" y="${H-5}" text-anchor="middle">${xLabel}</text>`;
 for(const s of series){if(s.points[0].low!==undefined){const band=s.points.map((p,i)=>(i?'L':'M')+x(p.x)+','+y(p.high)).join(' ')+s.points.slice().reverse().map(p=>'L'+x(p.x)+','+y(p.low)).join(' ')+'Z';svg+=`<path d="${band}" fill="${s.color}" opacity=".12"/>`;}
  svg+=`<path class="line" d="${s.points.map((p,i)=>(i?'L':'M')+x(p.x)+','+y(p.y)).join(' ')}" stroke="${s.color}"/>`;
  if(s.points.length<=10)svg+=s.points.map(p=>`<circle cx="${x(p.x)}" cy="${y(p.y)}" r="4" fill="${s.color}"/>`).join('');
 }
 host.innerHTML=`<div class="chart gr-chart"><svg tabindex="0" role="img" aria-label="${label}. Use arrow keys to inspect values." viewBox="0 0 ${W} ${H}">${svg}</svg><div class="chart-tip" hidden></div></div><div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${escape(s.name)}</span>`).join('')}</div>`;
 let index=0;const element=host.querySelector('svg'),tip=host.querySelector('.chart-tip');const show=i=>{index=Math.max(0,Math.min(series[0].points.length-1,i));tip.hidden=false;tip.innerHTML=`<strong>${xLabel}: ${xFormat(series[0].points[index].x)}</strong>`+series.map(s=>{const p=s.points[index];return `<p>${escape(s.name)}: ${format(p.y)}${p.low===undefined?'':`<br>10th–90th: ${format(p.low)}–${format(p.high)}`}</p>`;}).join('');};
 element.onpointermove=e=>{const rect=element.getBoundingClientRect(),v=minX+((e.clientX-rect.left)/rect.width*W-L)/(W-L-R)*(maxX-minX);show(series[0].points.reduce((best,p,i)=>Math.abs(p.x-v)<Math.abs(series[0].points[best].x-v)?i:best,0));};element.onpointerleave=()=>tip.hidden=true;element.onfocus=()=>show(index);element.onblur=()=>tip.hidden=true;element.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();show(index+(e.key==='ArrowRight'?1:-1));}};
}
function bars(selector,items,label,format){const max=Math.max(1e-9,...items.map(x=>x.value));root.querySelector(selector).innerHTML=`<h3>${label}</h3>${items.map(item=>`<div class="gr-bar"><span>${escape(item.name)} <strong>${format(item.value)}</strong></span><div style="width:${item.value/max*100}%;background:${item.color}"></div></div>`).join('')}`;}

let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(root){drawSchedulePreview();if(result&&mode==='compare')drawResults();}},150);});

function syncVolatility(){
 const custom=assumptions.volatilityMode==='custom',parametric=assumptions.model==='parametric';
 root.querySelector('#gr-stockVol').disabled=!custom&&!parametric;
 root.querySelector('#gr-volatilityMode').disabled=parametric;
 root.querySelector('#gr-vol-note').textContent=parametric?'Parametric model: uses the entered annual volatility.':custom?'Adjusted historical data: stock returns are transformed to your chosen annual volatility. Not unchanged historical outcomes. Sampled blocks can have different realized averages and volatility.':'Historical volatility: uses the variation in sampled U.S. stock returns.';
}
function renderStarting(){
 const host=root?.querySelector('#gr-start-results');if(!host)return;
 if(!startingResult){host.innerHTML='';return;}
 const a=startingResult.assumptions;
 host.innerHTML=`<h4>Starting withdrawal results</h4><p>${money(a.portfolio)} assets: ${money(a.portfolio-a.initialCash)} investments + ${money(a.initialCash)} cash. ${a.years} years · ${money(guardrailGoalTarget(a))} ending target in today’s dollars.</p><div class="table-scroll"><table><thead><tr><th>Target confidence</th><th>Annual withdrawals</th><th>Monthly</th><th>% of starting assets</th><th>Estimated confidence</th></tr></thead><tbody>${startingResult.starting.map(r=>`<tr><td>${pct(r.target)}</td><td>${r.unreachable?'Not achievable':money(r.spending)}</td><td>${r.unreachable?'—':money(r.spending/12)}</td><td>${r.unreachable?'—':pct(r.spending/a.portfolio)}</td><td>${pct(r.probability)}${r.unreachable?' at zero withdrawals':r.limited?' · target not precisely restored':''}</td></tr>`).join('')}</tbody></table></div><p class="hint">All withdrawal amounts are in today’s dollars. Unattainable strategies simulate starting at zero, not a successful confidence reset. Model check: mean error ${pp(startingResult.calibration.meanError)}, maximum ${pp(startingResult.calibration.maxError)}.${startingResult.calibration.maxError>.05?' Probability error exceeds 5 percentage points; interpret threshold differences cautiously.':''}</p><div class="gr-strategies">${strategies.map(s=>{const r=startingResult.starting.find(v=>Math.abs(v.target-s.target)<1e-9);return r?`<div class="metric"><div class="label">${escape(s.name)} · ${pct(s.target)} starting target</div><div class="value">${money(r.spending)}/year</div><div class="detail">${r.unreachable?'Target unattainable even at zero.':pct(r.spending/a.portfolio)+' of assets · '+pct(r.probability)+' estimated confidence'}</div></div>`:'';}).join('')}</div>`;
}
